  "conditions": {
    "basis_identification": {
      "status": "review",
      "note": "The record identifies specific dates, incidents, and actors (Supervisor, Coworkers 1-7), but the factual basis for the Agency's investigative conclusions and the FAD determination is not explicit—investigator findings and reasoning are summarized only through Complainant's and Supervisor's statements, without independent investigator analysis documented."
    },
    "reasoning_traceability": {
      "status": "gap",
      "note": "The record documents what was asked and stated but does not trace how the investigator weighed evidence, addressed contradictions (e.g., Supervisor's version vs. Complainant's), or reasoned from fact to conclusion; the FAD states Complainant 'failed to prove' discrimination but provides no documented analysis of proof standards applied."
    },
    "cold_reviewer_clarity": {
      "status": "gap",
      "note": "A reviewer years later cannot reconstruct why seven listed potential witnesses were never contacted, why the investigator only verified rather than questioned Complainant on eight of nine claims, or how the Agency reached its discrimination determination from the competing narratives in the ROI."
    },
    "accountability_support": {
      "status": "review",
      "note": "The record contains detailed chronology and multiple statements, but critical evidentiary gaps exist: no witness affidavits despite Complainant naming six coworkers, no documented investigator explanation for why those witnesses were not interviewed, and no explicit articulation of what evidence the Agency deemed insufficient for each claim."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "The record provides precise dates for nine alleged incidents (January 23 through February 20, 2019), complaint filing (March 13, 2019), investigation acceptance (May 8, 2019), and resignation effective date (February 8, 2019), enabling clear chronological reconstruction."
    }
  },
  "remediation_note": "To achieve compliance, the record must document the investigator's analysis of each claim against the legal standard for hostile work environment and discrimination, explain why identified witnesses were not interviewed, and articulate which evidence the Agency found insufficient to support Complainant's burden of proof.",
  "finding": {
    "ai_function": "summarization",
    "condition_triggered": "reasoning_traceability, cold_reviewer_clarity, accountability_support",
    "compliant_version": "A compliant version would include: (1) the investigator's documented findings on each of the nine claims with explicit application of the legal burden-of-proof standard; (2) a written explanation of why the seven named witnesses were not contacted or interviewed; (3) side-by-side analysis of conflicting statements (Complainant's harassment narrative vs. Supervisor's denial) with resolution of contradictions; (4) independent investigator conclusions, not merely a summary of party statements; and (5) the Agency's FAD reasoning that explains how each claim was evaluated against the evidence and why the Complainant failed to meet her burden on each discrete claim."
  }
}
